source = '''def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    if not points:
        return out

    rows = sorted(r for r, c in points)
    cols = sorted(c for r, c in points)
    mid_r = rows[(len(rows) - 1) // 2]
    mid_c = cols[(len(cols) - 1) // 2]
    horizontal_cost = max(cols) - min(cols) + sum(abs(r - mid_r) for r, c in points)
    vertical_cost = max(rows) - min(rows) + sum(abs(c - mid_c) for r, c in points)

    def paint(r, c):
        if out[r][c] == 0:
            out[r][c] = 3

    if horizontal_cost <= vertical_cost:
        for c in range(min(cols), max(cols) + 1):
            paint(mid_r, c)
        for r, c in points:
            for rr in range(min(r, mid_r), max(r, mid_r) + 1):
                paint(rr, c)
    else:
        for r in range(min(rows), max(rows) + 1):
            paint(r, mid_c)
        for r, c in points:
            for cc in range(min(c, mid_c), max(c, mid_c) + 1):
                paint(r, cc)
    return out
'''
